rue.source:
// Independent translation; the strict outer ABI is an explicit adapter.
fn main(...environment: Any) -> Any {
    assert environment is (Any, Any);
    assert environment.rest is (Any, Any);
    assert environment.rest.rest is nil;
    insertion_sort_by_keys(environment.first, environment.rest.first)
}

fn insertion_sort_by_keys(sorted: Any, insertions: Any) -> Any {
    if insertions is nil {
        sorted
    } else {
        assert insertions is (Any, Any);
        if (sorted is nil) || first_key(insertions) > first_key(sorted) {
            insertion_sort_by_keys((insertions.first, sorted), insertions.rest)
        } else {
            assert sorted is (Any, Any);
            let singleton = (insertions.first, nil);
            let inserted = insertion_sort_by_keys(sorted.rest, singleton);
            insertion_sort_by_keys((sorted.first, inserted), insertions.rest)
        }
    }
}

fn first_key(list: Any) -> Bytes {
    assert list is (Any, Any);
    let entry = list.first;
    assert entry is (Any, Any);
    let key = entry.first;
    assert key is Bytes;
    key
}

puzzles.source:
use chialisp_oxide::OwnedTree;

/// Apply the published insertion helper to arbitrary trees, without presorting
/// or validating keys that its original lazy branches would never inspect.
#[chialisp_oxide::puzzle]
pub fn puzzle<'a>(sorted: OwnedTree<'a>, insertions: OwnedTree<'a>) -> OwnedTree<'a> {
    insertion_sort_by_keys(sorted, insertions)
}

fn insertion_sort_by_keys<'a>(sorted: OwnedTree<'a>, insertions: OwnedTree<'a>) -> OwnedTree<'a> {
    if empty(&insertions) {
        sorted
    } else if empty(&sorted) || first_key(&insertions) > first_key(&sorted) {
        match insertions {
            OwnedTree::Pair(first, rest) => {
                insertion_sort_by_keys(OwnedTree::Pair(first, Box::new(sorted)), *rest)
            }
            OwnedTree::Atom(_) => panic!(),
        }
    } else {
        match sorted {
            OwnedTree::Pair(first_sorted, rest_sorted) => match insertions {
                OwnedTree::Pair(first, rest) => {
                    let singleton = OwnedTree::Pair(first, Box::new(OwnedTree::Atom(&[])));
                    let inserted = insertion_sort_by_keys(*rest_sorted, singleton);
                    insertion_sort_by_keys(OwnedTree::Pair(first_sorted, Box::new(inserted)), *rest)
                }
                OwnedTree::Atom(_) => panic!(),
            },
            OwnedTree::Atom(_) => panic!(),
        }
    }
}

fn empty(tree: &OwnedTree<'_>) -> bool {
    matches!(tree, OwnedTree::Atom([]))
}

fn first_key<'a>(list: &OwnedTree<'a>) -> &'a [u8] {
    match list {
        OwnedTree::Pair(entry, _) => match &**entry {
            OwnedTree::Pair(key, _) => match &**key {
                OwnedTree::Atom(bytes) => bytes,
                OwnedTree::Pair(_, _) => panic!(),
            },
            OwnedTree::Atom(_) => panic!(),
        },
        OwnedTree::Atom(_) => panic!(),
    }
}

source_dependencies.source:
//! Types and pure helpers shared by native Rust tests and CLVM compilation.
//!
//! Nominal types prevent source-level domain swaps. Their public constructors
//! establish no cryptographic or protocol invariant. The CLVM ABI validates the
//! inner representation, not a runtime nominal tag or constructor predicate.
#![no_std]

#[cfg(feature = "alloc")]
extern crate alloc;

pub use chialisp_oxide_macros::puzzle;

mod domain;
pub use domain::*;

mod tree;
pub use tree::*;

#[cfg(feature = "alloc")]
mod owned_tree;
#[cfg(feature = "alloc")]
pub use owned_tree::*;

//! Owned pair nodes with borrowed, immutable atom bytes.

use alloc::boxed::Box;

/// An ordinary Rust owned tree, preserving every atom byte and improper tail.
///
/// Native execution allocates ordinary `Box` pair nodes. CLVM compilation
/// lowers a restricted set of those operations to logical pairs; it does not
/// expose pointer or allocator APIs or make allocation and recursion free.
pub enum OwnedTree<'a> {
    Atom(&'a [u8]),
    Pair(Box<OwnedTree<'a>>, Box<OwnedTree<'a>>),
}

